function h({registerIndicator:p,sourceValues:m,nulls:y}){p({id:"oa-stddev",name:"Standard Deviation (STDDEV)",category:"Statistics",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:14,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"stddev",type:"line",title:"StdDev",style:{color:"#ffeb3b",lineWidth:2}}],calc(n,s){const c=Math.max(1,Math.floor(Number(s.period)||14)),d=m(n,s.source??"close"),u=new Array(n.length).fill(NaN),f=new Array(c).fill(NaN);let l=0,e=0,i=0,r=0;for(let t=0;t<n.length;t++){const o=f[l];Number.isFinite(o)&&(i-=o,r-=o*o,e-=1);const a=Number.isFinite(d[t])?d[t]:0;i+=a,r+=a*a,e+=1,f[l]=a,l=(l+1)%c,u[t]=e>1?Math.sqrt(Math.max(0,r/e-Math.pow(i/e,2))):0}return{stddev:y(u)}}})}export{h as default};
